example_item.example_item_data:
% Classer les battements d'un enregistrement simule et compter les ventriculaires.
recording = ecglab.simulate('Seconds', 60, 'Ectopic', 0.1, 'Seed', 1);
classes = ecglab.classify(recording);
sum(classes.label == 'V')

% Le resultat va directement a ecglab.validate pour la matrice de confusion.
recording = ecglab.simulate('Seconds', 60, 'Ectopic', 0.1, 'Seed', 1);
classes = ecglab.classify(recording);
agreement = ecglab.validate(classes.beats, recording.annotations, ...
  'Kind', 'beats', 'Table', 'dechazal');
agreement.matrix
